static const char *gsn = "gamesave";
static T_INT load_game()
{
  FILE *f = fopen(gsn,"rb");
  if (f != 0)
    {
      fread(cpu_get_mem()+0x400,0xFF,1,f);

      fclose(f);
    }
  return (f != 0);
}
static T_INT save_game()
{
    FILE *f = fopen(gsn,"wb");
    if (f != 0)
    {
      fwrite(cpu_get_mem()+0x400,0xFF,1,f);

      fclose(f);
    }
    return (f != 0);

}


